git checkout 940bd04 -- src/app/actions/billing.test.ts && cat > src/app/actions/portal.test.ts <<'EOF'
import { beforeEach, describe, expect, mock, test } from "bun:test"

const redirect = mock((url: string) => { throw Object.assign(new Error("NEXT_REDIRECT"), { url }) })
const auth = mock(async () => null as object | null)
const portal = mock(async (_params: object) => ({ url: "https://billing.stripe.test/p1" }))
const findUnique = mock(async (_args: object) => ({ stripeCustomerId: "cus_1" }) as object | null)
mock.module("next/headers", () => ({ headers: async () => new Headers({ origin: "http://localhost:3000" }) }))
mock.module("next/navigation", () => ({ redirect }))
mock.module("@/lib/auth", () => ({ auth }))
mock.module("@/lib/stripe", () => ({ stripe: { billingPortal: { sessions: { create: portal } } } }))
mock.module("@/lib/prisma", () => ({ prisma: { subscription: { findUnique } } }))
const { openPortal } = await import("./billing")
beforeEach(() => {
    for (const m of [redirect, auth, portal, findUnique]) m.mockClear()
    findUnique.mockImplementation(async () => ({ stripeCustomerId: "cus_1" }))
    auth.mockImplementation(async () => ({ user: { id: "u1", email: "a@b.co", name: "A" } }))
})

describe("openPortal", () => {
    test("signed out goes home without calling Stripe", async () => {
        auth.mockImplementation(async () => null)
        await expect(openPortal()).rejects.toMatchObject({ url: "/" })
        expect(portal).not.toHaveBeenCalled()
    })
    test("no subscription goes to subscribe without calling Stripe", async () => {
        findUnique.mockImplementation(async () => null)
        await expect(openPortal()).rejects.toMatchObject({ url: "/subscribe" })
        expect(portal).not.toHaveBeenCalled()
    })
    test("opens one portal session for the customer and sends the user there", async () => {
        await expect(openPortal()).rejects.toMatchObject({ url: "https://billing.stripe.test/p1" })
        expect(portal.mock.calls).toEqual([[{ customer: "cus_1", return_url: "http://localhost:3000/" }]])
    })
    test("looks the subscription up by the session user id", async () => {
        auth.mockImplementation(async () => ({ user: { id: "u2" } }))
        await expect(openPortal()).rejects.toMatchObject({ message: "NEXT_REDIRECT" })
        expect(findUnique.mock.calls).toEqual([[{ where: { userId: "u2" } }]])
    })
})
EOF
